"""Cart pricing."""

from cart.models import Line, Totals

BULK_MIN_QTY = 10


def _percent_off(cents: int, percent: int) -> int:
    """`percent` of `cents`, rounded to a whole cent with halves rounding up."""
    return (cents * percent + 50) // 100


def _parse_coupon(coupon: str) -> tuple[str, int]:
    kind, sep, number = coupon.partition(":")
    if not sep or kind not in ("PERCENT", "FIXED"):
        raise ValueError(f"invalid coupon: {coupon!r}")
    if not (number.isascii() and number.isdigit()):
        raise ValueError(f"invalid coupon: {coupon!r}")
    value = int(number)
    if kind == "PERCENT" and not 1 <= value <= 100:
        raise ValueError(f"percentage out of range in coupon: {coupon!r}")
    return kind, value


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"quantity must be at least 1: {line.sku!r}")
        if line.unit_cents < 0:
            raise ValueError(f"unit price must not be negative: {line.sku!r}")
    parsed = _parse_coupon(coupon) if coupon is not None else None

    subtotal = 0
    bulk_discount = 0
    for line in lines:
        amount = line.unit_cents * line.qty
        subtotal += amount
        if line.qty >= BULK_MIN_QTY:
            bulk_discount += _percent_off(amount, 10)

    remaining = subtotal - bulk_discount
    coupon_discount = 0
    if parsed is not None:
        kind, value = parsed
        coupon_discount = _percent_off(remaining, value) if kind == "PERCENT" else value
        coupon_discount = min(coupon_discount, remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal, discount, subtotal - discount)
